mod solution;

fn main() {
    let cases = [
    (r#"jobs=(d2,p100),(d1,p19),(d2,p27),(d1,p25),(d3,p15)"#, r#"142"#),
    (r#"jobs=(d1,p5),(d1,p10)"#, r#"10"#),
    (r#"
jobs=(d1,p5),(d1,p10)
"#, r#"10"#),
    (r#"  
jobs=(d2,p100),(d1,p19),(d2,p27),(d1,p25),(d3,p15)
  "#, r#"142"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS deadline-scheduling");
}
